effect.shader:
vec4 u_xlat0;
vec3 u_xlat1;
bvec3 u_xlatb1;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlatb1.xy = greaterThanEqual(acScreenNorm.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlat1.x = u_xlatb1.x ? float(1.0) : 0.0;
    u_xlat1.y = u_xlatb1.y ? float(1.0) : 0.0;
;
    u_xlat0 = u_xlat0 * u_xlat1.xxxx;
    u_xlat1.xz = (-acScreenNorm.xy) + vec2(1.0, 1.0);
    u_xlatb1.xz = greaterThanEqual(u_xlat1.xxzx, vec4(0.0, 0.0, 0.0, 0.0)).xz;
    u_xlat1.x = u_xlatb1.x ? float(1.0) : 0.0;
    u_xlat1.z = u_xlatb1.z ? float(1.0) : 0.0;
;
    u_xlat0 = u_xlat0 * u_xlat1.xxxx;
    u_xlat0 = u_xlat1.yyyy * u_xlat0;
    fragColor = u_xlat1.zzzz * u_xlat0;
    return;
}
